<script setup lang="ts">
import UserPicker from '../UserPicker.vue'
import { unitLabel } from '~~/shared/utils/team'
import type { TeamUnit,TeamPerson } from '~~/shared/types/team'
const queries=useAccountQueries(),data=ref<{units:TeamUnit[];}|null>(null),loading=ref(false),busy=ref(false),error=ref(''),success=ref('')
const unit=reactive({id:'',name:'',kind:'department' as TeamUnit['kind'],parentId:'',brand:'none'})
const person=ref<TeamPerson|null>(null),assigned=ref<string[]>([])
const kinds=[{label:'Компания',value:'company'},{label:'Отдел',value:'department'},{label:'Должность',value:'role'}]
const parentOptions=computed(()=>data.value?.units.filter(item=>item.kind===(unit.kind==='role'?'department':'company')).map(item=>({label:unitLabel(item.id,data.value!.units),value:item.id}))??[])
const roleOptions=computed(()=>data.value?.units.map(item=>({label:unitLabel(item.id,data.value!.units),value:item.id}))??[])
async function load(){loading.value=true;error.value='';try{data.value=await queries.read('admin-team','/api/admin/team',{force:true})}catch(failure:any){error.value=failure?.data?.message||'Настройки команды недоступны'}finally{loading.value=false}}
watch(person,value=>{assigned.value=value?[...value.roleIds]:[]})
watch(()=>unit.kind,()=>{if(!parentOptions.value.some(option=>option.value===unit.parentId))unit.parentId=parentOptions.value[0]?.value??''})
function edit(value?:TeamUnit){Object.assign(unit,{id:value?.id??'',name:value?.name??'',kind:value?.kind??'department',parentId:value?.parentId??'',brand:value?.brand??'none'})}
async function mutate(action:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await action();await queries.invalidate('admin-team','team','team-search','admin-team-search','team-profile','profile');await load();success.value='Изменения сохранены'}catch(failure:any){error.value=failure?.data?.message||'Не удалось сохранить изменения'}finally{busy.value=false}}
async function saveUnit(){await mutate(()=>sharedRequest('/api/admin/team/units',{method:'PUT',body:{...(unit.id?{id:unit.id}:{}),name:unit.name,kind:unit.kind,parentId:unit.kind==='company'?null:unit.parentId,brand:unit.kind==='company'&&unit.brand!=='none'?unit.brand:null}}));if(!error.value)edit()}
async function saveRoles(){if(person.value)await mutate(()=>sharedRequest('/api/admin/team/assignments',{method:'PUT',body:{userId:person.value!.id,roleIds:assigned.value}}))}
onMounted(load)
</script>
<template><div class="admin-team-settings"><div class="team-page-heading"><div><h1>Команда и роли</h1><p>Создавайте компании, отделы и должности. Назначайте компании, отделы и должности каждому аккаунту самостоятельно.</p></div><UButton color="neutral" variant="outline" label="Обновить" icon="i-lucide-refresh-cw" :loading="loading" @click="load"/></div><UAlert v-if="error" color="error" :description="error" class="mb-5"/><UAlert v-if="success" color="success" :description="success" class="mb-5"/><div class="admin-team-grid"><UCard><template #header><h2 class="font-semibold">Структура команды</h2></template><button v-for="item in data?.units??[]" :key="item.id" class="admin-team-unit" @click="edit(item)"><UIcon :name="item.kind==='company'?'i-lucide-building-2':item.kind==='department'?'i-lucide-git-branch':'i-lucide-badge'"/><span>{{ unitLabel(item.id,data?.units??[]) }}</span><UIcon name="i-lucide-pencil"/></button><form class="mt-5 space-y-4" @submit.prevent="saveUnit"><h3 class="font-medium">{{ unit.id?'Изменить элемент':'Новый элемент' }}</h3><UFormField label="Тип"><USelect v-model="unit.kind" :items="kinds" :disabled="!!unit.id" class="w-full"/></UFormField><UFormField label="Название" required><UInput v-model="unit.name" required :maxlength="80" class="w-full" placeholder="Например, Fullstack-разработчик"/></UFormField><UFormField v-if="unit.kind!=='company'" :label="unit.kind==='role'?'Отдел':'Компания'" required><USelect v-model="unit.parentId" :items="parentOptions" class="w-full" placeholder="Выберите родительский элемент"/></UFormField><UFormField v-else label="Бренд для участников без отдела"><USelect v-model="unit.brand" :items="[{label:'Не задан',value:'none'},{label:'Magnat',value:'magnat'},{label:'Light',value:'light'}]" class="w-full"/></UFormField><div class="flex gap-2"><UButton type="submit" label="Сохранить" :loading="busy" :disabled="!unit.name.trim()||unit.kind!=='company'&&!unit.parentId"/><UButton v-if="unit.id" color="neutral" variant="outline" label="Отменить выбор" @click="edit()"/></div></form></UCard><UCard><template #header><h2 class="font-semibold">Компания, отдел и должности участника</h2></template><div class="space-y-5"><UFormField label="Участник"><UserPicker v-model="person" admin :disabled="busy"/></UFormField><template v-if="person"><UFormField label="Назначенные компания, отдел и должности"><USelectMenu v-model="assigned" :items="roleOptions" value-key="value" multiple class="w-full" placeholder="Выберите компанию, отдел или должность"/></UFormField><p class="text-xs text-slate-500 leading-6">Назначение компаний, отделов и должностей доступно только в этой админ-панели. Можно указать отдел без обязательной должности. Участник не может менять их в своём профиле. Эти должности не выдают права администратора сайта или хранилищ.</p><UButton label="Сохранить роли участника" icon="i-lucide-user-check" :loading="busy" @click="saveRoles"/></template><p v-else class="team-muted">Найдите участника по ФИО, почте или Telegram.</p></div></UCard></div></div></template>
